    /** Memasang aksi tombol menu awal. Dipanggil sebelum form ditampilkan. */
    public void setSiap() {
        tombolLogin.addActionListener(e -> {
            LoginView login = new LoginView();
            view.util.Navigasi.tutupDanBuka(this, login);
        });
        tombolKeluar.addActionListener(e -> {
            DialogKeluar dialog = new DialogKeluar();
            dialog.setLocationRelativeTo(this);
            dialog.setVisible(true);
        });
    }
